import baseProducts from "@/demo/products.base.json";
import extraProducts from "@/demo/products.extra.json";
import { grams, inr, plural } from "@/lib/format";
import { pickSuggestions, reasonFor, sourceFor, understandText } from "@/lib/coach";
import { toView, type ProductView } from "@/lib/product";
import type { CartCoachApi, Product } from "./types";

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));

// The JSON fixtures are generated by backend/cmd/seed, so their diet values are valid.
const products = [...baseProducts, ...extraProducts] as Product[];
const views: ProductView[] = products.map(toView);
const byId = new Map(views.map((v) => [v.id, v]));

/** Runs the whole backend in the browser: generated sample data and a rule-based Coach. */
export const demoApi: CartCoachApi = {
  requiresSignIn: false,
  async signUp(name, email) {
    return { id: 0, email, name };
  },
  async logIn(email) {
    return { id: 0, email, name: "Demo" };
  },
  async currentUser() {
    return null;
  },
  async signOut() {},
  async getProfile() {
    return null;
  },
  async saveProfile() {},
  async listDecisions() {
    return [];
  },
  async addDecision() {},

  async listProducts() {
    await delay(250);
    return products;
  },

  async understandGoal(text) {
    await delay(1100);
    return understandText(text);
  },

  async suggestItems({ profile, cart, excluded_product_ids }) {
    await delay(700);
    const lines = cart.flatMap((l) => {
      const product = byId.get(l.product_id);
      return product ? [{ product, quantity: l.quantity }] : [];
    });
    const picks = pickSuggestions({ products: views, profile, cart: lines, excluded: excluded_product_ids ?? [] });
    const protein = picks.reduce((a, p) => a + (p.packProtein ?? 0), 0);
    const cost = picks.reduce((a, p) => a + p.price, 0);
    return {
      suggestions: picks.map((p) => ({
        product_id: p.id,
        protein_g: p.packProtein ?? 0,
        price: p.price,
        reason: reasonFor(p),
      })),
      log: picks.length
        ? {
            title: `Coach suggests ${plural(picks.length, "item", "items")} (+${grams(protein)} g protein, +${inr(cost)})`,
            detail: picks.map(sourceFor).join(" | "),
          }
        : { title: "No suggestions needed", detail: "Your goal is covered, or nothing fits your details and budget." },
    };
  },
};
